    }
    case 'hound': {
      p(ctx, -12, -12, 24, 8, C(c));
      p(ctx, -14, -16, 7, 6, C(dark));
      p(ctx, -9, -19, 4, 5, C(dark)); p(ctx, -2, -20, 4, 5, C(dark));
      p(ctx, -6, -15, 3, 3, '#ff4d6d'); p(ctx, 2, -15, 3, 3, '#ff4d6d');
