    }
    case 'elemental': {
      p(ctx, -10, -30, 20, 22, C(c));
      p(ctx, -7, -36, 14, 8, C(light));
      p(ctx, -4, -32, 3, 3, '#fff'); p(ctx, 2, -33, 3, 3, '#fff');
      p(ctx, -12, -25, 4, 10, C(dark)); p(ctx, 8, -25, 4, 10, C(dark));
