      p(ctx, -4, -35, 9, 9, C('#d19a88'));
      p(ctx, -6, -38, 2, 4, C(dark)); p(ctx, 4, -38, 2, 4, C(dark));
      p(ctx, -3, -32, 2, 2, '#ffd166'); p(ctx, 2, -32, 2, 2, '#ffd166');
      // wings
      p(ctx, -10, -30, 8, 2, C(shade(c, -0.2)));
      p(ctx, -14, -34, 6, 5, C(dark));
      p(ctx, 3, -30, 8, 2, C(shade(c, -0.2)));
