/* ============================================================
   AETHERIA — UI
   Mobile-first, dark-fantasy, high-contrast readability.
   ============================================================ */

:root {
  --ink: #0b0912;
  --ink-2: #100d1a;
  --panel: #171321;
  --panel-2: #1e192b;
  --panel-3: #272036;
  --line: rgba(230, 196, 106, 0.18);
  --line-strong: rgba(230, 196, 106, 0.4);
  --gold: #e6c46a;
  --gold-2: #f7e6a8;
  --gold-dim: #a88b45;
  --text: #f1ebdd;
  --muted: #a79fb2;
  --muted-2: #7b7388;
  --green: #65d67a;
  --blue: #5aa9ff;
  --red: #ff5d73;
  --purple: #b079ff;
  --orange: #ffb23e;
  --serif: Georgia, 'Times New Roman', 'Palatino Linotype', serif;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --shadow: 0 18px 55px rgba(0, 0, 0, 0.55);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { height: 100%; margin: 0; padding: 0; }
body {
  background: var(--ink);
  color: var(--text);
  font-family: var(--sans);
  overflow: hidden;
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }
::-webkit-scrollbar { width: 7px; height: 7px; }
::-webkit-scrollbar-thumb { background: rgba(230, 196, 106, 0.25); border-radius: 99px; }
::-webkit-scrollbar-track { background: transparent; }

#app { position: fixed; inset: 0; overflow: hidden; background: #08070d; }
#gameCanvas {
  position: absolute; inset: 0; width: 100%; height: 100%;
  display: block; touch-action: none; image-rendering: pixelated;
}
#vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 42%, rgba(4, 3, 9, 0.34) 100%),
    linear-gradient(to bottom, rgba(4, 3, 9, 0.35), transparent 18%, transparent 78%, rgba(4, 3, 9, 0.42));
  mix-blend-mode: multiply;
}

/* ============================== HUD ============================== */
#hud { position: absolute; inset: 0; pointer-events: none; z-index: 10; }
#hud > * { pointer-events: none; }
#hud button, #hud .quick-btn, #hud #joystick, #hud #questTracker { pointer-events: auto; }

.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 10px; padding: calc(10px + var(--safe-b) * 0) 12px 0;
}
.hud-left { width: min(250px, 62vw); display: flex; flex-direction: column; gap: 6px; }
.portrait-card {
  display: flex; align-items: center; gap: 9px; padding: 6px 9px 6px 6px;
  background: linear-gradient(135deg, rgba(28, 23, 42, 0.92), rgba(13, 11, 20, 0.88));
  border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 4px 22px rgba(0,0,0,0.35);
  backdrop-filter: blur(6px);
}
.portrait-ring {
  width: 42px; height: 42px; flex: none; border-radius: 50%;
  display: grid; place-items: center; font-size: 21px;
  background: radial-gradient(circle at 40% 30%, #3d3153, #171120);
  border: 1px solid var(--line-strong);
  box-shadow: inset 0 0 18px rgba(230,196,106,0.12);
}
.char-name { font-family: var(--serif); font-size: 15px; letter-spacing: .3px; color: var(--gold-2); line-height: 1.1; }
.char-sub { font-size: 10px; color: var(--muted); margin-top: 3px; letter-spacing: .3px; }
.char-sub b { color: var(--text); }
.bars { display: flex; flex-direction: column; gap: 4px; }
.bar {
  position: relative; height: 15px; border-radius: 6px; overflow: hidden;
  background: rgba(8, 7, 14, 0.82); border: 1px solid rgba(255,255,255,0.08);
  box-shadow: inset 0 2px 6px rgba(0,0,0,0.55);
}
.bar .bar-fill { height: 100%; width: 50%; transition: width .18s ease; }
.bar span { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 9px; font-weight: 700; letter-spacing: .4px; text-shadow: 0 1px 2px #000; color: #fff; }
.bar.hp .bar-fill { background: linear-gradient(180deg, #ff6b7d, #b51f35); }
.bar.mana .bar-fill { background: linear-gradient(180deg, #6db7ff, #2451b6); }
.bar.xp { height: 8px; }
.bar.xp .bar-fill { background: linear-gradient(90deg, #8b6a1e, var(--gold), #fff0b0); }
.bar.xp span { font-size: 7px; }
.region-chip {
  align-self: flex-start; margin-top: 1px; display: flex; align-items: center; gap: 5px;
  padding: 3px 9px; border-radius: 99px; font-size: 10px; letter-spacing: .6px;
  background: rgba(12, 10, 18, 0.78); border: 1px solid var(--line); color: var(--gold-2);
}
.region-chip .chev { color: var(--gold); font-size: 8px; }

.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 7px; }
.resource-pills { display: flex; gap: 6px; }
.pill {
  display: flex; align-items: center; gap: 5px; padding: 5px 9px; border-radius: 99px;
  background: rgba(12, 10, 18, 0.86); border: 1px solid var(--line); font-size: 11px;
  box-shadow: 0 3px 16px rgba(0,0,0,0.3);
}
.pill b { font-weight: 700; letter-spacing: .3px; }
.pill.gold span { color: var(--gold); }
.pill.gems span { color: #8fe2ff; }
.quick-row { display: flex; gap: 5px; }
.quick-btn {
  width: 38px; height: 38px; border-radius: 10px; border: 1px solid var(--line);
  background: linear-gradient(160deg, rgba(38, 31, 55, 0.9), rgba(14, 11, 21, 0.92));
  color: var(--text); display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 0; transition: transform .12s ease, border-color .12s ease;
}
.quick-btn:active { transform: scale(.93); border-color: var(--gold); }
.quick-btn span { font-size: 15px; line-height: 1; }
.quick-btn i { font-style: normal; font-size: 7px; color: var(--muted); margin-top: 2px; }

.minimap-wrap {
  position: absolute; top: 126px; right: 12px; width: 108px;
  border-radius: 12px; overflow: hidden; border: 1px solid var(--line);
  background: rgba(8,7,14,0.8); box-shadow: var(--shadow);
}
#minimap { display: block; width: 100%; height: auto; image-rendering: pixelated; }
.minimap-label {
  display: flex; flex-direction: column; align-items: center; padding: 3px 4px 4px;
  font-size: 8px; letter-spacing: .5px; color: var(--gold-2);
  border-top: 1px solid rgba(255,255,255,0.06); background: rgba(12,10,18,0.92);
}
.minimap-label em { font-style: normal; color: var(--muted-2); font-size: 7px; margin-top: 1px; }

.quest-tracker {
  position: absolute; top: 248px; left: 12px; width: min(214px, 53vw);
  padding: 9px 10px; border-radius: 11px; border: 1px solid var(--line);
  background: linear-gradient(160deg, rgba(26,21,38,0.9), rgba(12,10,18,0.85));
  box-shadow: 0 8px 28px rgba(0,0,0,0.35); backdrop-filter: blur(5px); cursor: pointer;
}
.qt-head { display: flex; align-items: center; gap: 6px; font-family: var(--serif); font-size: 12px; color: var(--gold-2); }
.qt-icon { color: var(--gold); font-size: 10px; }
.qt-desc { font-size: 9px; line-height: 1.35; color: var(--muted); margin: 4px 0 5px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.qt-progress { height: 4px; border-radius: 9px; background: rgba(255,255,255,0.08); overflow: hidden; }
.qt-progress > div { height: 100%; width: 0; background: linear-gradient(90deg, var(--gold-dim), var(--gold)); transition: width .2s; }
.qt-count { font-size: 8px; color: var(--muted); margin-top: 3px; text-align: right; }

.boss-bar {
  position: absolute; top: 116px; left: 50%; transform: translateX(-50%);
  width: min(560px, 58vw); padding: 6px 10px 8px; border-radius: 11px;
  background: rgba(14, 8, 14, 0.85); border: 1px solid rgba(255, 90, 60, 0.35);
  box-shadow: 0 8px 30px rgba(80,0,0,0.35); z-index: 12;
}
.boss-title { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--serif); font-size: 12px; color: #ffb08a; margin-bottom: 4px; }
.boss-title em { font-style: normal; font-size: 9px; color: var(--muted); }
.boss-track { height: 10px; border-radius: 6px; background: rgba(0,0,0,0.6); overflow: hidden; border: 1px solid rgba(255,255,255,0.08); }
#bossFill { height: 100%; width: 100%; background: linear-gradient(180deg, #ff7a5c, #a61e24); transition: width .18s; }

.event-feed {
  position: absolute; left: 12px; bottom: calc(150px + var(--safe-b)); width: min(270px, 52vw);
  display: flex; flex-direction: column; gap: 3px; pointer-events: none;
}
.feed-line { font-size: 9px; color: rgba(240,232,215,0.75); background: rgba(8,7,14,0.55); padding: 3px 7px; border-radius: 4px; width: fit-content; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; animation: feedIn .3s ease; }
.feed-line.gold { color: var(--gold-2); }
@keyframes feedIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

.interact-prompt {
  position: absolute; left: 50%; bottom: calc(116px + var(--safe-b)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 99px;
  background: rgba(10,8,16,0.88); border: 1px solid var(--line-strong);
  font-size: 11px; color: var(--gold-2); box-shadow: 0 6px 22px rgba(0,0,0,0.4);
  animation: promptPulse 2s ease-in-out infinite;
}
.interact-prompt .key { display: grid; place-items: center; width: 17px; height: 17px; border-radius: 4px; background: rgba(230,196,106,0.15); border: 1px solid var(--line-strong); font-size: 9px; font-weight: 800; }
@keyframes promptPulse { 0%,100% { box-shadow: 0 6px 22px rgba(0,0,0,0.4); } 50% { box-shadow: 0 6px 22px rgba(230,196,106,0.18); } }

/* ---------------- controls ---------------- */
#controls { position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute; left: calc(18px + var(--safe-l)); bottom: calc(18px + var(--safe-b));
  width: 120px; height: 120px; border-radius: 50%; pointer-events: auto;
  background: radial-gradient(circle at 50% 50%, rgba(30,24,44,0.55), rgba(10,8,16,0.35));
  border: 1px solid rgba(230,196,106,0.16); touch-action: none;
}
.joy-ring { position: absolute; inset: 10px; border-radius: 50%; border: 1px dashed rgba(230,196,106,0.18); }
.joy-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
  border-radius: 50%; background: radial-gradient(circle at 38% 32%, #4b3d68, #211a33);
  border: 1px solid var(--line-strong); box-shadow: 0 6px 18px rgba(0,0,0,.4), inset 0 0 12px rgba(230,196,106,0.12);
  will-change: transform;
}
.joy-hint { position: absolute; bottom: 6px; width: 100%; text-align: center; font-size: 7px; letter-spacing: 2px; color: rgba(230,196,106,0.35); }

.action-cluster { position: absolute; right: calc(12px + var(--safe-r)); bottom: calc(16px + var(--safe-b)); width: 190px; height: 196px; pointer-events: none; }
.act {
  position: absolute; pointer-events: auto; border-radius: 50%; border: 1px solid rgba(230,196,106,0.28);
  background: radial-gradient(circle at 38% 30%, rgba(54,44,76,0.95), rgba(18,14,28,0.96));
  color: var(--gold-2); display: flex; flex-direction: column; align-items: center; justify-content: center;
  box-shadow: 0 6px 22px rgba(0,0,0,0.45), inset 0 0 18px rgba(230,196,106,0.07);
  transition: transform .1s ease, filter .1s; overflow: hidden; touch-action: none;
}
.act:active { transform: scale(.94); filter: brightness(1.2); }
.act span { font-size: 22px; line-height: 1; }
.act i { font-style: normal; font-size: 8px; color: var(--muted); margin-top: 2px; letter-spacing: .4px; }
.act-attack { right: 0; bottom: 0; width: 78px; height: 78px; border-color: rgba(255, 180, 90, .42); background: radial-gradient(circle at 38% 30%, #653a2e, #2a1718); }
.act-attack span { font-size: 30px; color: #ffd8a0; }
.act-attack i { color: #ffcf9a; }
.act-skill { right: 86px; bottom: 6px; width: 62px; height: 62px; border-color: rgba(130,180,255,.35); background: radial-gradient(circle at 38% 30%, #2c3a63, #171629); }
.act-skill span { font-size: 23px; color: #b8d4ff; }
.act-potion { right: 3px; bottom: 86px; width: 50px; height: 50px; }
.act-potion span { font-size: 19px; }
.act-interact { right: 63px; bottom: 75px; width: 54px; height: 54px; border-color: rgba(140,255,190,.35); }
.act-interact span { font-size: 20px; color: #b6ffce; }
.act-mini { width: 42px; height: 42px; }
.act-mini span { font-size: 16px; }
.act-mount { right: 16px; bottom: 148px; }
.act-auto { right: 66px; bottom: 152px; }
.act-auto.active { border-color: var(--green); box-shadow: 0 0 18px rgba(101,214,122,0.25); }
.act-auto.active span { color: var(--green); }
.act-skill .cooldown-mask { position: absolute; inset: 0; background: conic-gradient(rgba(8,6,14,0.78) var(--cd, 0deg), transparent 0); pointer-events: none; }
.act-skill .cooldown-text { position: absolute; inset: 0; display: grid; place-items: center; font-size: 13px; font-weight: 800; color: #fff; text-shadow: 0 1px 4px #000; pointer-events: none; }
.act.interact-ready { animation: readyGlow 1.6s ease-in-out infinite; }
@keyframes readyGlow { 0%,100% { box-shadow: 0 0 0 rgba(140,255,190,0); } 50% { box-shadow: 0 0 22px rgba(140,255,190,0.28); } }

.death-flash { position: absolute; inset: 0; background: radial-gradient(circle, transparent 30%, rgba(160,10,20,0.45)); opacity: 0; pointer-events: none; transition: opacity .5s; }
.death-flash.on { opacity: 1; }

/* ============================== START ============================== */
.start-screen {
  position: absolute; inset: 0; z-index: 60; overflow: hidden;
  background:
    radial-gradient(ellipse at 68% 32%, rgba(94, 74, 140, 0.28), transparent 55%),
    radial-gradient(ellipse at 24% 80%, rgba(120, 60, 40, 0.18), transparent 55%),
    linear-gradient(160deg, #0b0914, #11101d 48%, #08070d);
  display: flex; flex-direction: column;
}
.start-screen::before {
  content: ''; position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,0.5) 1px, transparent 1px), radial-gradient(rgba(230,196,106,0.35) 1px, transparent 1px);
  background-size: 137px 137px, 211px 211px; background-position: 0 0, 60px 90px;
  opacity: .18; pointer-events: none;
}
.stars { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.stars::before, .stars::after {
  content: ''; position: absolute; inset: -50%;
  background-image: radial-gradient(circle, rgba(255,240,200,.8) 1px, transparent 1.6px);
  background-size: 190px 230px; opacity: .2; animation: drift 60s linear infinite;
}
.stars::after { background-size: 290px 310px; opacity: .12; animation-duration: 95s; animation-direction: reverse; }
@keyframes drift { to { transform: translate(190px, 230px); } }

.start-inner {
  position: relative; z-index: 2; flex: 1;
  display: grid; grid-template-columns: minmax(220px, 340px) minmax(320px, 620px);
  align-items: center; justify-content: center; gap: 28px; padding: 32px 24px;
}
.start-art { display: grid; place-items: center; }
#titlePreview {
  width: 280px; height: 360px; filter: drop-shadow(0 24px 50px rgba(0,0,0,0.5));
  animation: floatArt 7s ease-in-out infinite;
}
@keyframes floatArt { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.start-copy { max-width: 620px; }
.eyebrow { font-size: 9px; letter-spacing: 4px; color: var(--gold-dim); margin-bottom: 8px; }
.logo {
  margin: 0; font-family: var(--serif); font-weight: 400;
  font-size: clamp(54px, 9vw, 104px); line-height: .92; letter-spacing: .12em;
  background: linear-gradient(180deg, #fff7d4 5%, #e6c46a 45%, #9a7430 95%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 20px rgba(230,196,106,0.22));
}
.tagline { font-family: var(--serif); font-size: clamp(13px, 1.5vw, 17px); line-height: 1.65; color: #c8c0d0; margin: 14px 0 24px; }
.start-buttons { display: flex; flex-direction: column; gap: 9px; max-width: 320px; }
.start-meta { display: flex; gap: 16px; margin-top: 18px; font-size: 9px; color: var(--muted-2); letter-spacing: .6px; }
.start-footer {
  position: relative; z-index: 2; display: flex; justify-content: space-between; gap: 12px;
  padding: 14px 20px calc(14px + var(--safe-b)); font-size: 8px; color: var(--muted-2); letter-spacing: .8px; border-top: 1px solid rgba(255,255,255,0.04);
}

/* ============================== BUTTONS ============================== */
.btn {
  position: relative; border: 1px solid var(--line-strong); border-radius: 9px;
  padding: 12px 18px; background: linear-gradient(180deg, rgba(41,34,57,0.95), rgba(22,18,33,0.95));
  color: var(--text); font-size: 12px; letter-spacing: .7px; font-weight: 600;
  transition: transform .1s ease, filter .15s, border-color .15s; overflow: hidden;
}
.btn:hover { filter: brightness(1.12); border-color: rgba(230,196,106,0.6); }
.btn:active { transform: scale(.98); }
.btn-primary {
  background: linear-gradient(180deg, #d6af55, #8f6f2c); color: #171018;
  border-color: #f0d994; text-shadow: 0 1px 0 rgba(255,255,255,0.25);
  box-shadow: 0 8px 26px rgba(180,140,50,0.2), inset 0 1px 0 rgba(255,255,255,0.4);
  font-weight: 800;
}
.btn-primary:hover { filter: brightness(1.06); }
.btn-ghost { background: rgba(16,13,24,0.6); }
.btn-danger { border-color: rgba(255,90,90,0.4); background: rgba(80,20,26,0.55); color: #ffb6b6; }
.btn-sm { padding: 7px 10px; font-size: 10px; border-radius: 7px; letter-spacing: .3px; }
.btn-wide { width: 100%; padding: 14px; font-size: 13px; }
.icon-btn { width: 34px; height: 34px; border-radius: 8px; border: 1px solid var(--line); background: rgba(20,16,30,0.85); color: var(--muted); display: grid; place-items: center; }
.icon-btn:hover { color: var(--text); border-color: var(--line-strong); }
.btn[disabled] { opacity: .38; pointer-events: none; }
.btn .tag { margin-left: auto; }

/* ============================== CREATION ============================== */
.creation-screen {
  position: absolute; inset: 0; z-index: 55; overflow-y: auto; overflow-x: hidden;
  background:
    radial-gradient(ellipse at 30% 22%, rgba(90,70,140,0.22), transparent 55%),
    linear-gradient(160deg, #0d0b16, #13101e 55%, #08070e);
  padding: 16px 14px calc(30px + var(--safe-b));
}
.creation-shell { max-width: 1020px; margin: 0 auto; }
.creation-head { display: flex; justify-content: space-between; align-items: flex-start; padding: 6px 2px 16px; }
.creation-head h2 { margin: 2px 0 0; font-family: var(--serif); font-weight: 400; font-size: clamp(26px, 4vw, 40px); letter-spacing: .04em; color: var(--gold-2); }
.creation-body { display: grid; grid-template-columns: 300px 1fr; gap: 22px; align-items: start; }
.creation-preview {
  position: sticky; top: 10px; border: 1px solid var(--line); border-radius: 16px;
  background: linear-gradient(170deg, rgba(32,26,48,0.8), rgba(13,11,21,0.9));
  padding: 12px 12px 14px; text-align: center; box-shadow: var(--shadow);
}
#createPreview { width: 100%; height: auto; aspect-ratio: 280/360; }
.preview-name { font-family: var(--serif); font-size: 20px; color: var(--gold-2); margin-top: -2px; }
.preview-sub { font-size: 10px; letter-spacing: 1.2px; color: var(--muted); text-transform: uppercase; margin-top: 3px; }
.preview-stats { display: flex; justify-content: center; gap: 12px; margin-top: 10px; font-size: 9px; color: var(--muted); flex-wrap: wrap; }
.preview-stats b { color: var(--text); display: block; font-size: 12px; }
.creation-form {
  border: 1px solid var(--line); border-radius: 16px; padding: 18px;
  background: linear-gradient(170deg, rgba(26,21,40,0.86), rgba(11,10,18,0.94));
  box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 16px;
}
.field { display: flex; flex-direction: column; gap: 5px; font-size: 10px; color: var(--muted); letter-spacing: .6px; }
.field input {
  background: rgba(8,7,14,0.8); border: 1px solid var(--line); border-radius: 8px;
  padding: 11px 12px; color: var(--text); font-size: 15px; outline: none; letter-spacing: .5px;
}
.field input:focus { border-color: var(--line-strong); box-shadow: 0 0 0 3px rgba(230,196,106,0.08); }
.opt-group { display: flex; flex-direction: column; gap: 7px; }
.opt-group.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.opt-label { font-size: 10px; letter-spacing: 1px; text-transform: uppercase; color: var(--gold); }
.opt-label em { font-style: normal; color: var(--muted-2); font-size: 8px; letter-spacing: .4px; text-transform: none; margin-left: 5px; }
.choice-row { display: flex; flex-wrap: wrap; gap: 6px; }
.choice {
  border: 1px solid var(--line); border-radius: 8px; background: rgba(14,11,22,0.75);
  color: var(--muted); padding: 9px 12px; font-size: 10px; letter-spacing: .3px; text-align: left;
  transition: all .12s ease;
}
.choice:hover { border-color: var(--line-strong); color: var(--text); }
.choice.selected { border-color: var(--gold); background: rgba(230,196,106,0.13); color: var(--gold-2); box-shadow: 0 0 0 1px rgba(230,196,106,0.2) inset; }
.choice small { display: block; font-size: 8px; color: var(--muted-2); margin-top: 2px; letter-spacing: .2px; }
.choice.class-choice { min-width: 112px; flex: 1; padding: 11px; }
.choice.class-choice b { display: block; font-family: var(--serif); font-size: 14px; font-weight: 400; margin-bottom: 2px; }
.choice.faction-choice { flex: 1; min-width: 110px; }
.hair-row .choice { min-width: 88px; }
.swatch { width: 34px; height: 34px; border-radius: 50%; border: 2px solid transparent; background-clip: padding-box; }
.swatch.selected { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(230,196,106,0.22); }
.swatch.eye { width: 30px; height: 30px; }
.fine { font-size: 8px; color: var(--muted-2); line-height: 1.5; margin: 0; }

/* ============================== LOADING ============================== */
.loading-screen {
  position: absolute; inset: 0; z-index: 70; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 40%, #1b1528, #07060c 70%); overflow: hidden;
}
.loading-bg { position: absolute; inset: 0; background: radial-gradient(circle at 50% 50%, rgba(230,196,106,0.06), transparent 55%); animation: loadPulse 3s ease-in-out infinite; }
@keyframes loadPulse { 0%,100% { opacity: .6; transform: scale(1); } 50% { opacity: 1; transform: scale(1.06); } }
.loading-inner { position: relative; z-index: 2; max-width: 620px; padding: 24px; text-align: center; }
.loading-kicker { font-size: 8px; letter-spacing: 5px; color: var(--gold-dim); margin-bottom: 12px; }
.loading-inner h2 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: clamp(40px, 8vw, 76px); letter-spacing: .06em; color: var(--gold-2); text-shadow: 0 4px 30px rgba(230,196,106,0.2); }
.loading-epithet { font-family: var(--serif); font-style: italic; font-size: clamp(14px, 2vw, 20px); color: var(--muted); margin-top: 4px; }
.loading-lore { font-size: 10px; line-height: 1.8; color: var(--muted-2); max-width: 440px; margin: 18px auto 24px; letter-spacing: .3px; }
.loading-track { width: min(320px, 72vw); height: 3px; margin: 0 auto; background: rgba(255,255,255,0.08); border-radius: 4px; overflow: hidden; }
#loadingFill { width: 0; height: 100%; background: linear-gradient(90deg, var(--gold-dim), var(--gold-2)); animation: loadBar 1.8s ease-in-out infinite; }
@keyframes loadBar { 0% { width: 0; } 60% { width: 82%; } 100% { width: 100%; } }
.loading-hint { font-size: 8px; letter-spacing: 2px; color: var(--muted-2); margin-top: 10px; text-transform: uppercase; }
.loading-runes { position: absolute; bottom: 26px; width: 100%; text-align: center; font-family: var(--serif); font-size: 14px; letter-spacing: 18px; color: rgba(230,196,106,0.2); animation: runePulse 4s ease-in-out infinite; }
@keyframes runePulse { 0%,100% { opacity: .5; } 50% { opacity: 1; } }

/* ============================== MODAL ============================== */
.modal-root { position: absolute; inset: 0; z-index: 50; display: flex; align-items: center; justify-content: center; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(4,3,8,0.72); backdrop-filter: blur(3px); }
.modal-sheet {
  position: relative; width: min(940px, calc(100vw - 28px)); max-height: 88vh;
  border: 1px solid var(--line); border-radius: 16px; overflow: hidden;
  background: linear-gradient(170deg, #1b1628, #0d0b14 75%);
  box-shadow: var(--shadow); display: flex; flex-direction: column;
  animation: modalIn .18s ease;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(10px) scale(.985); } to { opacity: 1; transform: none; } }
.modal-head {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  padding: 13px 14px; border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(38,31,55,0.7), rgba(21,17,32,0.4));
}
.modal-title-wrap { display: flex; align-items: center; gap: 9px; min-width: 0; }
.modal-title-wrap > span { color: var(--gold); font-size: 16px; }
.modal-head h3 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 19px; letter-spacing: .04em; color: var(--gold-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.modal-body { padding: 14px 15px calc(18px + var(--safe-b)); overflow-y: auto; overscroll-behavior: contain; touch-action: pan-y; }

/* ============================== TOAST ============================== */
.toast-host { position: absolute; top: 14px; left: 50%; transform: translateX(-50%); z-index: 90; display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none; width: min(520px, 92vw); }
.toast {
  max-width: 100%; padding: 8px 13px; border-radius: 8px; font-size: 10px; line-height: 1.4;
  background: rgba(18,14,28,0.95); border: 1px solid var(--line); color: var(--text);
  box-shadow: 0 8px 26px rgba(0,0,0,0.5); animation: toastIn .22s ease; text-align: center;
  backdrop-filter: blur(4px);
}
.toast.success { border-color: rgba(101,214,122,0.5); color: #c8ffd4; }
.toast.warn { border-color: rgba(255,178,62,0.5); color: #ffe0ad; }
.toast.danger { border-color: rgba(255,93,115,0.55); color: #ffc2ca; }
.toast.region { font-family: var(--serif); font-size: 13px; padding: 10px 18px; color: var(--gold-2); border-color: var(--line-strong); }
.toast.loot { border-color: rgba(230,196,106,0.3); }
.toast.small { font-size: 9px; padding: 6px 10px; }
.toast.out { animation: toastOut .25s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

/* ============================== DEATH ============================== */
.death-overlay { position: absolute; inset: 0; z-index: 45; display: grid; place-content: center; text-align: center; background: radial-gradient(circle, rgba(70,5,14,0.25), rgba(5,2,6,0.7)); pointer-events: none; animation: deathIn .6s ease; }
@keyframes deathIn { from { opacity: 0; } to { opacity: 1; } }
.death-word { font-family: var(--serif); font-size: clamp(28px, 7vw, 64px); letter-spacing: .22em; color: #ffb0b8; text-shadow: 0 0 40px rgba(255,40,60,0.45); }
.death-overlay p { font-size: 11px; color: var(--muted); letter-spacing: 1px; }

/* ============================== PANEL COMPONENTS ============================== */
.panel-lead { font-size: 10px; line-height: 1.6; color: var(--muted); margin: 0 0 12px; }
.panel-lead b { color: var(--gold-2); }
.panel-grid { display: grid; gap: 12px; }
.grid-2 { grid-template-columns: 1fr 1fr; }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.card {
  border: 1px solid var(--line); border-radius: 11px; padding: 12px;
  background: linear-gradient(160deg, rgba(35,28,50,0.6), rgba(16,13,25,0.75));
}
.card.tight { padding: 9px; }
.card h4 { margin: 0 0 6px; font-family: var(--serif); font-weight: 400; font-size: 14px; color: var(--gold-2); }
.card .sub { font-size: 9px; color: var(--muted); line-height: 1.45; }
.section-title { display: flex; align-items: center; gap: 8px; font-family: var(--serif); font-size: 14px; color: var(--gold); margin: 16px 0 8px; letter-spacing: .4px; }
.section-title:first-child { margin-top: 0; }
.section-title::after { content: ''; flex: 1; height: 1px; background: linear-gradient(90deg, var(--line), transparent); }
.note { font-size: 9px; line-height: 1.55; color: var(--muted-2); background: rgba(255,255,255,0.025); border-left: 2px solid rgba(230,196,106,0.3); padding: 7px 9px; border-radius: 0 6px 6px 0; }
.note.warn { border-left-color: rgba(255,178,62,0.5); color: #d9bd8a; }
.note.danger { border-left-color: rgba(255,93,115,0.6); color: #e3a5ad; }
.row { display: flex; align-items: center; gap: 8px; }
.row.between { justify-content: space-between; }
.row.wrap { flex-wrap: wrap; }
.spacer { flex: 1; }
.muted { color: var(--muted); }
.tiny { font-size: 8px; }
.mt8 { margin-top: 8px; } .mt12 { margin-top: 12px; } .mb8 { margin-bottom: 8px; }
.gold-text { color: var(--gold); } .green-text { color: var(--green); } .red-text { color: var(--red); } .blue-text { color: var(--blue); }
.tag {
  display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 8px; letter-spacing: .4px;
  background: rgba(255,255,255,0.07); border: 1px solid rgba(255,255,255,0.08); color: var(--muted);
}
.tag.gold { color: var(--gold-2); background: rgba(230,196,106,0.1); border-color: rgba(230,196,106,0.25); }
.tag.green { color: #b8ffc8; background: rgba(101,214,122,0.1); border-color: rgba(101,214,122,0.25); }
.tag.red { color: #ffc2ca; background: rgba(255,93,115,0.1); border-color: rgba(255,93,115,0.25); }
.tag.blue { color: #bcd8ff; background: rgba(90,169,255,0.1); border-color: rgba(90,169,255,0.25); }
.seg { display: inline-flex; padding: 3px; border-radius: 8px; background: rgba(8,7,14,0.55); border: 1px solid var(--line); gap: 2px; flex-wrap: wrap; }
.seg button { border: 0; background: transparent; color: var(--muted); padding: 5px 10px; border-radius: 6px; font-size: 9px; letter-spacing: .3px; }
.seg button.active { background: rgba(230,196,106,0.14); color: var(--gold-2); }
.tabs { display: flex; gap: 5px; flex-wrap: wrap; margin-bottom: 10px; }
.tabs button { border: 1px solid var(--line); background: rgba(12,10,18,0.7); color: var(--muted); padding: 6px 11px; border-radius: 99px; font-size: 9px; }
.tabs button.active { border-color: var(--gold); color: var(--gold-2); background: rgba(230,196,106,0.1); }
.progress { height: 6px; border-radius: 99px; background: rgba(255,255,255,0.08); overflow: hidden; }
.progress > div { height: 100%; background: linear-gradient(90deg, var(--gold-dim), var(--gold)); }
.stat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px 12px; }
.stat-line { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; padding: 3px 0; border-bottom: 1px solid rgba(255,255,255,0.045); color: var(--muted); }
.stat-line b { color: var(--text); font-weight: 600; }
.stat-line .pos { color: var(--green); }
.big-stat { text-align: center; padding: 8px 6px; border: 1px solid var(--line); border-radius: 8px; background: rgba(10,8,16,0.45); }
.big-stat b { display: block; font-family: var(--serif); font-size: 18px; color: var(--gold-2); }
.big-stat span { font-size: 8px; letter-spacing: .8px; color: var(--muted); text-transform: uppercase; }

/* items */
.item-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(146px, 1fr)); gap: 8px; }
.item-card {
  position: relative; border: 1px solid var(--line); border-left: 3px solid var(--rar, var(--gold));
  border-radius: 8px; padding: 8px 9px; background: rgba(13,11,20,0.72); text-align: left; color: var(--text);
  display: flex; flex-direction: column; gap: 3px; min-height: 68px;
  transition: border-color .12s, transform .1s, background .12s;
}
.item-card:hover { background: rgba(35,28,50,0.6); transform: translateY(-1px); }
.item-card .iname { font-family: var(--serif); font-size: 12px; line-height: 1.2; color: var(--rar, var(--text)); overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.item-card .imeta { font-size: 8px; color: var(--muted); letter-spacing: .2px; }
.item-card .itop { display: flex; justify-content: space-between; align-items: flex-start; gap: 4px; }
.item-card .iicon { font-size: 16px; opacity: .9; }
.tier-badge { position: absolute; top: 6px; right: 7px; font-size: 8px; font-weight: 800; padding: 1px 4px; border-radius: 3px; background: rgba(0,0,0,0.45); color: var(--gold); }
.restrict { font-size: 8px; color: #ffb0b0; }
.item-detail-head { display: flex; gap: 13px; align-items: flex-start; }
.item-icon-lg { width: 68px; height: 68px; flex: none; display: grid; place-items: center; font-size: 30px; border-radius: 11px; border: 1px solid var(--line); background: radial-gradient(circle at 40% 30%, rgba(255,255,255,0.08), rgba(10,8,16,0.7)); }
.item-name-lg { font-family: var(--serif); font-size: 21px; line-height: 1.2; margin: 0 0 3px; }
.item-restrict { font-size: 9px; color: #ffb0b0; margin-top: 3px; }
.bonus-line { font-size: 9px; color: #b8ffc8; }
.slot-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.slot {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  padding: 8px 4px; border: 1px dashed rgba(230,196,106,0.2); border-radius: 8px;
  background: rgba(10,8,16,0.45); font-size: 8px; color: var(--muted); min-height: 60px; text-align: center;
}
.slot.filled { border-style: solid; border-color: var(--rar, var(--line)); background: rgba(30,24,44,0.55); }
.slot .si { font-size: 17px; }
.slot .sn { font-size: 8px; line-height: 1.2; color: var(--text); overflow: hidden; text-overflow: ellipsis; max-width: 100%; white-space: nowrap; }
.slot .sl { font-size: 7px; color: var(--muted-2); letter-spacing: .5px; text-transform: uppercase; }

/* cosmetic preview */
.preview-box { border: 1px solid var(--line); border-radius: 12px; overflow: hidden; background: radial-gradient(circle at 50% 40%, rgba(70,55,110,0.22), rgba(10,8,16,0.6)); }
.preview-box canvas { width: 100%; height: auto; display: block; }

/* shop */
.shop-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 9px; }
.shop-card { border: 1px solid var(--line); border-radius: 11px; padding: 11px; background: linear-gradient(160deg, rgba(38,31,55,0.55), rgba(14,11,22,0.8)); display: flex; flex-direction: column; gap: 7px; }
.shop-card .sc-top { display: flex; align-items: center; gap: 8px; }
.shop-card .sc-icon { width: 36px; height: 36px; display: grid; place-items: center; border-radius: 9px; font-size: 19px; background: rgba(255,255,255,0.05); border: 1px solid var(--line); flex: none; }
.shop-card h4 { margin: 0; font-family: var(--serif); font-weight: 400; font-size: 14px; color: var(--gold-2); line-height: 1.1; }
.shop-card p { margin: 0; font-size: 9px; line-height: 1.5; color: var(--muted); flex: 1; }
.price-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 2px; }
.price { font-size: 11px; color: var(--gold); font-weight: 700; }
.price small { color: var(--muted-2); font-weight: 400; font-size: 8px; }
.owned { font-size: 8px; color: var(--green); letter-spacing: .5px; }
.test-banner { border: 1px solid rgba(255,178,62,0.35); background: linear-gradient(90deg, rgba(80,55,15,0.5), rgba(25,18,10,0.45)); color: #ffdca0; font-size: 9px; line-height: 1.5; padding: 8px 11px; border-radius: 8px; margin-bottom: 12px; }

/* quests */
.quest-card { border: 1px solid var(--line); border-radius: 9px; padding: 10px 11px; background: rgba(13,11,20,0.62); display: flex; flex-direction: column; gap: 5px; }
.quest-card.active { border-color: rgba(230,196,106,0.35); }
.quest-card.complete { border-color: rgba(101,214,122,0.4); }
.quest-card h4 { margin: 0; font-family: var(--serif); font-size: 13px; font-weight: 400; color: var(--gold-2); }
.quest-card p { margin: 0; font-size: 9px; line-height: 1.45; color: var(--muted); }
.quest-meta { display: flex; flex-wrap: wrap; gap: 5px; }
.quest-reward { font-size: 9px; color: var(--gold); }

/* map */
.region-card { border: 1px solid var(--line); border-radius: 10px; padding: 11px; background: linear-gradient(160deg, rgba(35,28,50,0.55), rgba(13,11,20,0.8)); display: flex; flex-direction: column; gap: 5px; }
.region-card.current { border-color: var(--gold); box-shadow: 0 0 0 1px rgba(230,196,106,0.14) inset; }
.region-card h4 { margin: 0; font-family: var(--serif); font-size: 15px; font-weight: 400; color: var(--gold-2); }
.region-card .epi { font-size: 9px; font-style: italic; color: var(--muted); }
.region-card .lvl { font-size: 8px; color: var(--muted-2); }
.region-card .desc { font-size: 9px; line-height: 1.45; color: var(--muted-2); }
.region-card .row { margin-top: 3px; }
.dungeon-card { border: 1px solid rgba(255,100,80,0.22); border-radius: 9px; padding: 9px 10px; background: rgba(40,15,18,0.35); }

/* blacksmith */
.fuse-card { border: 1px solid var(--line); border-radius: 10px; padding: 10px; background: rgba(13,11,20,0.68); display: flex; flex-direction: column; gap: 6px; }
.fuse-head { display: flex; align-items: center; gap: 8px; }
.fuse-icon { width: 38px; height: 38px; border-radius: 8px; display: grid; place-items: center; font-size: 18px; background: rgba(255,255,255,0.05); border: 1px solid var(--line); }
.fuse-card h4 { margin: 0; font-family: var(--serif); font-size: 13px; font-weight: 400; color: var(--rar, var(--gold-2)); }
.fuse-progress { display: flex; gap: 3px; }
.fuse-pip { width: 14px; height: 6px; border-radius: 2px; background: rgba(255,255,255,0.1); }
.fuse-pip.on { background: var(--gold); }

/* enchant */
.select-list { display: flex; flex-direction: column; gap: 5px; max-height: 260px; overflow-y: auto; padding-right: 2px; }
.select-item { text-align: left; border: 1px solid var(--line); border-left: 3px solid var(--rar, var(--line-strong)); border-radius: 7px; padding: 7px 9px; background: rgba(13,11,20,0.65); color: var(--text); display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.select-item.selected { border-color: var(--gold); background: rgba(230,196,106,0.08); }
.select-item .sm { font-size: 8px; color: var(--muted); }

/* market */
.list-row { border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; background: rgba(13,11,20,0.6); display: flex; align-items: center; gap: 9px; }
.list-row .lr-main { flex: 1; min-width: 0; }
.list-row .lr-name { font-size: 10px; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.list-row .lr-sub { font-size: 8px; color: var(--muted); }
input.price-input { width: 110px; background: rgba(8,7,14,0.8); border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; font-size: 11px; color: var(--gold); outline: none; }

/* economy */
.eco-bars { display: flex; flex-direction: column; gap: 5px; }
.eco-bar { display: grid; grid-template-columns: 90px 1fr 70px; gap: 7px; align-items: center; font-size: 9px; }
.eco-bar .track { height: 5px; background: rgba(255,255,255,0.07); border-radius: 99px; overflow: hidden; }
.eco-bar .track div { height: 100%; background: linear-gradient(90deg, var(--gold-dim), var(--gold)); }
.eco-bar.out .track div { background: linear-gradient(90deg, #7a3030, #e46a6a); }
.eco-bar b { text-align: right; color: var(--muted); font-weight: 500; }
.ledger { max-height: 220px; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }
.ledger-line { display: flex; justify-content: space-between; gap: 8px; font-size: 8px; padding: 3px 0; border-bottom: 1px solid rgba(255,255,255,0.04); color: var(--muted); }
.ledger-line .in { color: var(--green); } .ledger-line .out { color: var(--red); }

/* misc */
.kv { display: flex; justify-content: space-between; gap: 10px; font-size: 10px; padding: 5px 0; border-bottom: 1px solid rgba(255,255,255,0.05); }
.kv b { color: var(--gold-2); font-weight: 600; }
.list-plain { display: flex; flex-direction: column; gap: 6px; }
.empty { text-align: center; padding: 26px 12px; color: var(--muted-2); font-size: 10px; }
.empty span { display: block; font-size: 26px; margin-bottom: 6px; opacity: .5; }
.toggle-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 9px 0; border-bottom: 1px solid rgba(255,255,255,0.05); font-size: 10px; }
.switch { width: 38px; height: 21px; border-radius: 99px; background: rgba(255,255,255,0.12); border: 1px solid var(--line); position: relative; transition: background .15s; flex: none; }
.switch::after { content: ''; position: absolute; top: 2px; left: 2px; width: 15px; height: 15px; border-radius: 50%; background: var(--muted); transition: transform .15s, background .15s; }
.switch.on { background: rgba(101,214,122,0.25); border-color: rgba(101,214,122,0.5); }
