    p(ctx, -shoulder - 1, -29, 3, 2, shade(pal.metal, 0.25));
    p(ctx, shoulder - 3, -30, 5, 6, pal.metal);
    p(ctx, shoulder - 2, -29, 3, 2, shade(pal.metal, 0.25));
